--- Líneas para mostrar el proceso de recuperación
-----------------------------------------------------------------------------------------
-- Cargar fuente de texto
Font.ftInit();
fontARCA = Font.ftLoad("System/Medios/Font/PublicPixel.ttf");

-- Refrescar pantalla
function refrescar()
	Screen.flip()
end

function PAL_Test() -- Verifica si la configuración es PAL
	local actual = System.currentDirectory()
	if doesFileExist(actual .."/System/Respaldo/PAL") == true and doesFileExist(actual .."/System/Respaldo/NTSC") == false then
		Screen.setMode(PAL, 640, 512, CT24, INTERLACED, FIELD)
	end
end

function puerto_usb() -- Verifica que el programa no se ejecute desde el segundo puerto
	local actual = System.currentDirectory()
	local buscar = System.listDirectory("mass1:")
	local res_y_tex = 0
	if doesFileExist(actual .."/System/Respaldo/PAL") then
		res_y_tex = 34
	end
	if actual == "mass1:/RETROLauncher" or buscar ~= nil then
		while true do
			Screen.clear(Color.new(0,0,0))
			if actual == "mass1:/RETROLauncher" then
				Font.ftPrint(fontARCA,5,140+res_y_tex,0,640,448,"Warning\nThis program was created to run from the first\nport(USB) of PS2.\nPlease, reconnect the USB to the first port and\nrestart the program.",Color.new(128,128,128))
			elseif buscar ~= nil then
				Font.ftPrint(fontARCA,5,140+res_y_tex,0,640,448,"Warning\nUSB storage device detected on second port(USB)\nPlease, Disconnect the USB from the second port\nand restart the program.",Color.new(128,128,128))
			end
			refrescar()
		end
	end
end

-- Mostrar barra de progreso durante la reubicación de archivos
function barra_de_progreso(FONDO,estado,indi_rest,pal,LOADING)
	Screen.clear(Color.new(0,0,0))
	local actual = System.currentDirectory()
	local res_x, res_y_tex, res_y = 640,0,448
	if doesFileExist(actual .."/System/Respaldo/PAL") then
		res_x, res_y_tex, res_y = 640,34,512
	end
	Graphics.drawScaleImage(FONDO,-5,0,res_x+5,res_y,Color.new(0,80,120))
	Graphics.drawScaleImage(LOADING,0,0,res_x,res_y)
	Graphics.drawRect(-5,278-3+res_y_tex,650,25,Color.new(0,0,0))
	local lista_indi_rest = {"Atari 2600","Neo Geo Pocket","Nintendo Famicom","Nintendo Game Boy","Nintendo Game Boy Advance","Nintendo Game Boy Color","Nintendo Super Famicom","Sega Game Gear","Sega Master System","Sega Megadrive","Sega SG-1000"}
	local indi_X_fix = {-14,10,24,28,82,70,64,10,34,10,-5}
	if pal == false then
		Font.ftPrint(fontARCA,150-indi_X_fix[indi_rest],278+res_y_tex,0,0,8,"-RELOCATING ".. lista_indi_rest[indi_rest] .."-",Color.new(128,128,128))
	elseif pal == true then
		Font.ftPrint(fontARCA,150-indi_X_fix[indi_rest]-26,278+res_y_tex,0,0,8,"-RELOCATING ".. lista_indi_rest[indi_rest] .." PAL-",Color.new(128,128,128))
	elseif pal == nil then
		Font.ftPrint(fontARCA,150,278+res_y_tex,0,0,8,"-RELOCATING ALL SETTINGS-",Color.new(128,128,128))
	end
	Font.ftPrint(fontARCA,152,304+res_y_tex,0,0,8,"█████████████████████████",Color.new(128,128,128))
	if estado ~= 0 then
		Font.ftPrint(fontARCA,152,304+res_y_tex,0,0,8,string.sub("█████████████████████████",1,estado),Color.new(0,80,120))
	end
	refrescar()
end

